const vertShader = `
precision mediump float;

attribute vec3 aPosition;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;
uniform float depth;

varying vec3 vPosition;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;

	vPosition = aPosition + vec3(0.5, 0.5, depth);
}
`;

const fragShader = `
precision mediump float;

uniform float depth;

varying vec3 vPosition;

bool inFractal(vec3 position) {
	for(int i = 0; i < 5; i++) {
		int sum = 0;
		if(position.x > 1.0 / 3.0 && position.x < 2.0 / 3.0) sum ++;
		if(position.y > 1.0 / 3.0 && position.y < 2.0 / 3.0) sum ++;
		if(position.z > 1.0 / 3.0 && position.z < 2.0 / 3.0) sum ++;

		if(sum < 2) {
			position = mod(position * 3.0, 1.0);
		} else {
			return false;
		}
	}

	return true;
}

void main() {
	if(inFractal(vPosition)) {
  	gl_FragColor = vec4(vPosition, 1.0);
	} else {
  	gl_FragColor = vec4(0.0, 0.0, 0.0, mod(depth, 0.005));
	}
}
`;

